insert into public.translations (locale, key, value) values
  ('pt-BR', 'whatsNew.item.planRefusal.title', $json$"Recusar um plano não o aprova mais"$json$::jsonb),
  ('en', 'whatsNew.item.planRefusal.title', $json$"Refusing a plan no longer approves it"$json$::jsonb),
  ('es', 'whatsNew.item.planRefusal.title', $json$"Rechazar un plan ya no lo aprueba"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.planRefusal.title', $json$"拒绝计划不再等于批准"$json$::jsonb),
  ('hi', 'whatsNew.item.planRefusal.title', $json$"योजना अस्वीकार करना अब उसे स्वीकृत नहीं करता"$json$::jsonb),
  ('ar', 'whatsNew.item.planRefusal.title', $json$"رفض الخطة لم يعد يوافق عليها"$json$::jsonb),
  ('fr', 'whatsNew.item.planRefusal.title', $json$"Refuser un plan ne l’approuve plus"$json$::jsonb),
  ('ru', 'whatsNew.item.planRefusal.title', $json$"Отказ от плана больше не одобряет его"$json$::jsonb),
  ('ja', 'whatsNew.item.planRefusal.title', $json$"計画を断っても承認扱いにならなくなりました"$json$::jsonb),
  ('de', 'whatsNew.item.planRefusal.title', $json$"Einen Plan abzulehnen genehmigt ihn nicht mehr"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.planRefusal.detail', $json$"Com um plano esperando no chat, a mensagem que o recusava ou pedia para mudá-lo (\"não aprovo\", \"o plano está errado, refaça\", \"não implemente ainda\") era lida como aprovação, e no Auto o chat ia para o Desenvolvimento construir o plano que você recusou. Agora recusa, negação ou pedido de outro plano não o aprova: o Jev lê a mensagem como pedido novo."$json$::jsonb),
  ('en', 'whatsNew.item.planRefusal.detail', $json$"With a plan waiting in the chat, a message that refused it or asked to change it (\"I don't approve\", \"the plan is wrong, redo it\", \"don't implement it yet\") was read as approval, and in Auto the chat went to Development to build the plan you had refused. Now a refusal, a negation or a request for another plan does not approve it: Jev reads the message as a new request."$json$::jsonb),
  ('es', 'whatsNew.item.planRefusal.detail', $json$"Con un plan esperando en el chat, el mensaje que lo rechazaba o pedía cambiarlo (\"no lo apruebo\", \"el plan está mal, rehazlo\", \"no lo implementes todavía\") se leía como aprobación, y en Auto el chat pasaba a Desarrollo para construir el plan que rechazaste. Ahora un rechazo, una negación o el pedido de otro plan no lo aprueba: Jev lee el mensaje como una solicitud nueva."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.planRefusal.detail', $json$"聊天中有等待执行的计划时，拒绝它或要求修改它的消息（“我不同意”“计划不对，重做”“先别实现”）会被当作批准，在自动模式下聊天会进入开发模式去实现你拒绝的计划。现在，拒绝、否定或要求另做计划都不会批准它：Jev 会把这条消息当作新的请求。"$json$::jsonb),
  ('hi', 'whatsNew.item.planRefusal.detail', $json$"चैट में कोई योजना इंतज़ार कर रही हो, तो उसे अस्वीकार करने या बदलने को कहने वाला संदेश (\"मैं सहमत नहीं\", \"योजना गलत है, फिर से बनाओ\", \"अभी लागू मत करो\") स्वीकृति माना जाता था, और ऑटो में चैट डेवलपमेंट में जाकर वही योजना बनाने लगती थी जिसे आपने अस्वीकार किया था। अब अस्वीकार, निषेध या दूसरी योजना का अनुरोध उसे स्वीकृत नहीं करता: Jev संदेश को नया अनुरोध मानता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.planRefusal.detail', $json$"عندما تكون هناك خطة تنتظر في المحادثة، كانت الرسالة التي ترفضها أو تطلب تغييرها («لا أوافق»، «الخطة خاطئة، أعدها»، «لا تنفذها بعد») تُقرأ كموافقة، وفي الوضع التلقائي كانت المحادثة تنتقل إلى التطوير لبناء الخطة التي رفضتها. الآن لا يوافق الرفض أو النفي أو طلب خطة أخرى عليها: يقرأ Jev الرسالة كطلب جديد."$json$::jsonb),
  ('fr', 'whatsNew.item.planRefusal.detail', $json$"Avec un plan en attente dans le chat, le message qui le refusait ou demandait de le changer (« je n’approuve pas », « le plan est faux, refais-le », « ne l’implémente pas encore ») était lu comme une approbation, et en Auto le chat passait en Développement pour construire le plan que vous aviez refusé. Désormais, un refus, une négation ou la demande d’un autre plan ne l’approuve pas : Jev lit le message comme une nouvelle demande."$json$::jsonb),
  ('ru', 'whatsNew.item.planRefusal.detail', $json$"Когда в чате ждал план, сообщение, которое отклоняло его или просило изменить («не одобряю», «план неверный, переделай», «пока не реализуй»), читалось как одобрение, и в режиме «Авто» чат переходил в разработку, чтобы выполнить отклонённый вами план. Теперь отказ, отрицание или просьба о другом плане его не одобряют: Jev читает сообщение как новый запрос."$json$::jsonb),
  ('ja', 'whatsNew.item.planRefusal.detail', $json$"チャットに計画が待機しているとき、それを断る、または変更を求めるメッセージ（「承認しない」「計画が間違っている、作り直して」「まだ実装しないで」）が承認と読まれ、自動モードではチャットが開発モードに進み、断った計画を実装していました。今後は、拒否、否定、別の計画の依頼は計画を承認しません。Jev はそのメッセージを新しい依頼として読みます。"$json$::jsonb),
  ('de', 'whatsNew.item.planRefusal.detail', $json$"Wartete im Chat ein Plan, wurde eine Nachricht, die ihn ablehnte oder eine Änderung verlangte („ich stimme nicht zu“, „der Plan ist falsch, mach ihn neu“, „setz das noch nicht um“), als Genehmigung gelesen, und im Automatikmodus ging der Chat in die Entwicklung, um den abgelehnten Plan umzusetzen. Jetzt genehmigt eine Ablehnung, eine Verneinung oder die Bitte um einen anderen Plan ihn nicht: Jev liest die Nachricht als neue Anfrage."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.lateQuestion.title', $json$"Pergunta atrasada não trava mais a caixa de mensagem"$json$::jsonb),
  ('en', 'whatsNew.item.lateQuestion.title', $json$"Late questions no longer lock the message box"$json$::jsonb),
  ('es', 'whatsNew.item.lateQuestion.title', $json$"Una pregunta tardía ya no bloquea el cuadro de mensaje"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.lateQuestion.title', $json$"迟到的提问不再锁住消息框"$json$::jsonb),
  ('hi', 'whatsNew.item.lateQuestion.title', $json$"देर से आया प्रश्न अब संदेश बॉक्स को लॉक नहीं करता"$json$::jsonb),
  ('ar', 'whatsNew.item.lateQuestion.title', $json$"السؤال المتأخر لم يعد يقفل مربع الرسالة"$json$::jsonb),
  ('fr', 'whatsNew.item.lateQuestion.title', $json$"Une question tardive ne bloque plus la zone de message"$json$::jsonb),
  ('ru', 'whatsNew.item.lateQuestion.title', $json$"Запоздавший вопрос больше не блокирует поле сообщения"$json$::jsonb),
  ('ja', 'whatsNew.item.lateQuestion.title', $json$"遅れて届いた質問がメッセージ欄をロックしなくなりました"$json$::jsonb),
  ('de', 'whatsNew.item.lateQuestion.title', $json$"Verspätete Fragen sperren das Nachrichtenfeld nicht mehr"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.lateQuestion.detail', $json$"O Jev lê cada resposta para achar a pergunta dela alguns segundos depois de ela chegar. Se você já tinha mandado outra mensagem nesse meio-tempo, a pergunta antiga travava a caixa de mensagem por cima da conversa, e no Auto um plano sem pergunta ia sozinho para o Desenvolvimento, por cima do que você mandou. Agora a pergunta da resposta e esse passo automático só acontecem enquanto nada mais foi enviado depois dela."$json$::jsonb),
  ('en', 'whatsNew.item.lateQuestion.detail', $json$"Jev reads each answer to find its question a few seconds after it arrives. If you had already sent another message in the meantime, the old question locked the message box over the conversation, and in Auto a plan with no question went to Development by itself, on top of what you had sent. Now the answer's question and that automatic step only happen while nothing else was sent after it."$json$::jsonb),
  ('es', 'whatsNew.item.lateQuestion.detail', $json$"Jev lee cada respuesta para encontrar su pregunta unos segundos después de que llega. Si ya habías enviado otro mensaje entretanto, la pregunta vieja bloqueaba el cuadro de mensaje encima de la conversación, y en Auto un plan sin pregunta pasaba solo a Desarrollo, encima de lo que enviaste. Ahora la pregunta de la respuesta y ese paso automático solo ocurren mientras no se haya enviado nada después."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.lateQuestion.detail', $json$"Jev 会在回答到达几秒后读取它，找出其中的提问。如果你在此期间已经发送了另一条消息，旧的提问会压在当前对话上锁住消息框；在自动模式下，没有提问的计划还会自行进入开发模式，覆盖你刚发送的内容。现在，只有在其后没有发送其他消息时，回答的提问和这一自动步骤才会发生。"$json$::jsonb),
  ('hi', 'whatsNew.item.lateQuestion.detail', $json$"Jev हर जवाब आने के कुछ सेकंड बाद उसमें प्रश्न खोजता है। अगर इस बीच आप कोई और संदेश भेज चुके थे, तो पुराना प्रश्न बातचीत के ऊपर संदेश बॉक्स को लॉक कर देता था, और ऑटो में बिना प्रश्न वाली योजना अपने-आप डेवलपमेंट में चली जाती थी, आपके भेजे संदेश के ऊपर से। अब जवाब का प्रश्न और यह स्वचालित कदम तभी होते हैं जब उसके बाद कुछ और न भेजा गया हो।"$json$::jsonb),
  ('ar', 'whatsNew.item.lateQuestion.detail', $json$"يقرأ Jev كل إجابة ليجد سؤالها بعد وصولها ببضع ثوانٍ. إن كنت قد أرسلت رسالة أخرى في الأثناء، كان السؤال القديم يقفل مربع الرسالة فوق المحادثة، وفي الوضع التلقائي كانت الخطة التي بلا سؤال تنتقل وحدها إلى التطوير فوق ما أرسلته. الآن لا يحدث سؤال الإجابة ولا هذه الخطوة التلقائية إلا ما دام لم يُرسل شيء بعدها."$json$::jsonb),
  ('fr', 'whatsNew.item.lateQuestion.detail', $json$"Jev lit chaque réponse pour y trouver sa question quelques secondes après son arrivée. Si vous aviez déjà envoyé un autre message entre-temps, l’ancienne question bloquait la zone de message par-dessus la conversation, et en Auto un plan sans question passait seul en Développement, par-dessus ce que vous aviez envoyé. Désormais, la question de la réponse et cette étape automatique n’ont lieu que tant que rien d’autre n’a été envoyé après elle."$json$::jsonb),
  ('ru', 'whatsNew.item.lateQuestion.detail', $json$"Jev читает каждый ответ, чтобы найти в нём вопрос, через несколько секунд после его прихода. Если вы за это время уже отправили другое сообщение, старый вопрос блокировал поле сообщения поверх разговора, а в режиме «Авто» план без вопроса сам уходил в разработку поверх того, что вы отправили. Теперь вопрос из ответа и этот автоматический шаг происходят, только пока после ответа ничего больше не отправлено."$json$::jsonb),
  ('ja', 'whatsNew.item.lateQuestion.detail', $json$"Jev は各回答が届いて数秒後に、その中の質問を探します。その間に別のメッセージをすでに送っていた場合、古い質問が会話の上からメッセージ欄をロックし、自動モードでは質問のない計画が送った内容の上から自動で開発モードに進んでいました。今後は、回答の質問とこの自動ステップは、その後に何も送られていないときだけ行われます。"$json$::jsonb),
  ('de', 'whatsNew.item.lateQuestion.detail', $json$"Jev liest jede Antwort einige Sekunden nach ihrem Eintreffen, um ihre Frage zu finden. Hatten Sie in der Zwischenzeit schon eine andere Nachricht gesendet, sperrte die alte Frage das Nachrichtenfeld über dem Gespräch, und im Automatikmodus ging ein Plan ohne Frage von selbst in die Entwicklung, über das hinweg, was Sie gesendet hatten. Jetzt geschehen die Frage der Antwort und dieser automatische Schritt nur, solange danach nichts anderes gesendet wurde."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modeKept.title', $json$"O modo que você escolhe durante um pedido fica"$json$::jsonb),
  ('en', 'whatsNew.item.modeKept.title', $json$"The mode you pick during a request stays"$json$::jsonb),
  ('es', 'whatsNew.item.modeKept.title', $json$"El modo que eliges durante una solicitud se mantiene"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modeKept.title', $json$"请求期间你选择的模式会保留"$json$::jsonb),
  ('hi', 'whatsNew.item.modeKept.title', $json$"अनुरोध के दौरान चुना गया मोड बना रहता है"$json$::jsonb),
  ('ar', 'whatsNew.item.modeKept.title', $json$"الوضع الذي تختاره أثناء الطلب يبقى"$json$::jsonb),
  ('fr', 'whatsNew.item.modeKept.title', $json$"Le mode choisi pendant une demande est conservé"$json$::jsonb),
  ('ru', 'whatsNew.item.modeKept.title', $json$"Режим, выбранный во время запроса, сохраняется"$json$::jsonb),
  ('ja', 'whatsNew.item.modeKept.title', $json$"依頼の実行中に選んだモードが保たれます"$json$::jsonb),
  ('de', 'whatsNew.item.modeKept.title', $json$"Der während einer Anfrage gewählte Modus bleibt"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modeKept.detail', $json$"Quando o Jev passava o chat para Desenvolvimento num pedido e você escolhia outro modo enquanto ele rodava, o fim do pedido punha o Desenvolvimento de volta por cima da sua escolha. Agora a sua escolha fica."$json$::jsonb),
  ('en', 'whatsNew.item.modeKept.detail', $json$"When Jev switched a chat to Development during a request and you picked another mode while it ran, the end of the request put Development back over your choice. Now your choice stays."$json$::jsonb),
  ('es', 'whatsNew.item.modeKept.detail', $json$"Cuando Jev pasaba el chat a Desarrollo en una solicitud y elegías otro modo mientras se ejecutaba, el final de la solicitud volvía a poner Desarrollo encima de tu elección. Ahora tu elección se mantiene."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modeKept.detail', $json$"当 Jev 在某个请求中把聊天切换到开发模式，而你在请求运行期间选择了其他模式时，请求结束后会重新设为开发模式，覆盖你的选择。现在会保留你的选择。"$json$::jsonb),
  ('hi', 'whatsNew.item.modeKept.detail', $json$"जब Jev किसी अनुरोध में चैट को डेवलपमेंट में बदल देता था और अनुरोध चलते समय आप कोई और मोड चुनते थे, तो अनुरोध खत्म होने पर आपकी पसंद के ऊपर फिर से डेवलपमेंट लग जाता था। अब आपकी पसंद बनी रहती है।"$json$::jsonb),
  ('ar', 'whatsNew.item.modeKept.detail', $json$"عندما كان Jev ينقل المحادثة إلى التطوير في طلب ما واخترت وضعًا آخر أثناء تنفيذه، كانت نهاية الطلب تعيد التطوير فوق اختيارك. الآن يبقى اختيارك."$json$::jsonb),
  ('fr', 'whatsNew.item.modeKept.detail', $json$"Quand Jev passait le chat en Développement pendant une demande et que vous choisissiez un autre mode pendant son exécution, la fin de la demande remettait le Développement par-dessus votre choix. Désormais, votre choix est conservé."$json$::jsonb),
  ('ru', 'whatsNew.item.modeKept.detail', $json$"Когда Jev переключал чат в разработку во время запроса, а вы выбирали другой режим, пока он выполнялся, в конце запроса разработка снова ставилась поверх вашего выбора. Теперь ваш выбор сохраняется."$json$::jsonb),
  ('ja', 'whatsNew.item.modeKept.detail', $json$"Jev が依頼の中でチャットを開発モードに切り替え、実行中に別のモードを選んでも、依頼の終了時に開発モードが選択を上書きしていました。今後は選んだモードが保たれます。"$json$::jsonb),
  ('de', 'whatsNew.item.modeKept.detail', $json$"Wenn Jev den Chat in einer Anfrage in die Entwicklung schaltete und Sie währenddessen einen anderen Modus wählten, setzte das Ende der Anfrage die Entwicklung wieder über Ihre Wahl. Jetzt bleibt Ihre Wahl erhalten."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.clearStops.title', $json$"Limpar o chat para o pedido dele"$json$::jsonb),
  ('en', 'whatsNew.item.clearStops.title', $json$"Clearing a chat stops its request"$json$::jsonb),
  ('es', 'whatsNew.item.clearStops.title', $json$"Vaciar el chat detiene su solicitud"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.clearStops.title', $json$"清空聊天会停止其请求"$json$::jsonb),
  ('hi', 'whatsNew.item.clearStops.title', $json$"चैट साफ़ करने से उसका अनुरोध रुक जाता है"$json$::jsonb),
  ('ar', 'whatsNew.item.clearStops.title', $json$"مسح المحادثة يوقف طلبها"$json$::jsonb),
  ('fr', 'whatsNew.item.clearStops.title', $json$"Vider le chat arrête sa demande"$json$::jsonb),
  ('ru', 'whatsNew.item.clearStops.title', $json$"Очистка чата останавливает его запрос"$json$::jsonb),
  ('ja', 'whatsNew.item.clearStops.title', $json$"チャットを消去すると依頼が停止します"$json$::jsonb),
  ('de', 'whatsNew.item.clearStops.title', $json$"Das Leeren des Chats stoppt seine Anfrage"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.clearStops.detail', $json$"Limpar ou excluir um chat com um pedido rodando deixava o agente trabalhando sem ninguém ver, e no chat limpo a resposta dele aparecia sozinha, sem o pedido. Uma pergunta em aberto continuava travando a caixa de mensagem, e um pedido que esperava o limite de uso voltava vazio. Agora limpar ou excluir para o pedido, fecha a pergunta e cancela a espera, e nada da conversa antiga chega ao chat limpo."$json$::jsonb),
  ('en', 'whatsNew.item.clearStops.detail', $json$"Clearing or deleting a chat while its request ran left the agent working unseen, and in the cleared chat its answer showed up alone, without the request. A pending question stayed locking the message box, and a request waiting for the usage limit came back empty. Now clearing or deleting stops the request, closes the question and drops the wait, and nothing from the old conversation reaches the cleared chat."$json$::jsonb),
  ('es', 'whatsNew.item.clearStops.detail', $json$"Vaciar o eliminar un chat con una solicitud en curso dejaba al agente trabajando sin que nadie lo viera, y en el chat vaciado su respuesta aparecía sola, sin la solicitud. Una pregunta pendiente seguía bloqueando el cuadro de mensaje, y una solicitud que esperaba el límite de uso volvía vacía. Ahora vaciar o eliminar detiene la solicitud, cierra la pregunta y cancela la espera, y nada de la conversación anterior llega al chat vaciado."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.clearStops.detail', $json$"在请求运行时清空或删除聊天，代理仍会在无人察觉的情况下继续工作，清空后的聊天中还会单独出现它的回答，却没有对应的请求。未回答的提问仍会锁住消息框，等待用量上限恢复的请求会以空内容重新发送。现在，清空或删除会停止请求、关闭提问并取消等待，旧对话中的任何内容都不会进入已清空的聊天。"$json$::jsonb),
  ('hi', 'whatsNew.item.clearStops.detail', $json$"चलते अनुरोध वाली चैट को साफ़ करने या हटाने पर एजेंट बिना किसी के देखे काम करता रहता था, और साफ़ की गई चैट में उसका जवाब अकेला, बिना अनुरोध के दिखता था। खुला प्रश्न संदेश बॉक्स को लॉक किए रहता था, और उपयोग सीमा का इंतज़ार कर रहा अनुरोध खाली लौट आता था। अब साफ़ करने या हटाने पर अनुरोध रुक जाता है, प्रश्न बंद हो जाता है और इंतज़ार रद्द हो जाता है, और पुरानी बातचीत का कुछ भी साफ़ की गई चैट में नहीं आता।"$json$::jsonb),
  ('ar', 'whatsNew.item.clearStops.detail', $json$"كان مسح محادثة أو حذفها أثناء تنفيذ طلبها يترك الوكيل يعمل دون أن يراه أحد، وفي المحادثة الممسوحة كانت إجابته تظهر وحدها بلا الطلب. وكان السؤال المفتوح يبقى مقفلًا لمربع الرسالة، والطلب الذي ينتظر حد الاستخدام يعود فارغًا. الآن يوقف المسح أو الحذف الطلب، ويغلق السؤال، ويلغي الانتظار، ولا يصل شيء من المحادثة القديمة إلى المحادثة الممسوحة."$json$::jsonb),
  ('fr', 'whatsNew.item.clearStops.detail', $json$"Vider ou supprimer un chat pendant que sa demande s’exécutait laissait l’agent travailler sans que personne ne le voie, et dans le chat vidé sa réponse apparaissait seule, sans la demande. Une question en attente continuait de bloquer la zone de message, et une demande qui attendait la limite d’utilisation revenait vide. Désormais, vider ou supprimer arrête la demande, ferme la question et annule l’attente, et rien de l’ancienne conversation n’arrive dans le chat vidé."$json$::jsonb),
  ('ru', 'whatsNew.item.clearStops.detail', $json$"Очистка или удаление чата во время выполнения его запроса оставляли агента работать незаметно, а в очищенном чате его ответ появлялся сам по себе, без запроса. Открытый вопрос продолжал блокировать поле сообщения, а запрос, ждавший лимита использования, возвращался пустым. Теперь очистка или удаление останавливает запрос, закрывает вопрос и отменяет ожидание, и ничего из старого разговора не попадает в очищенный чат."$json$::jsonb),
  ('ja', 'whatsNew.item.clearStops.detail', $json$"依頼の実行中にチャットを消去または削除しても、エージェントは誰にも見えないまま作業を続け、消去したチャットには依頼のない回答だけが表示されていました。未回答の質問はメッセージ欄をロックしたままで、使用量の上限を待っていた依頼は空のまま再送されていました。今後は、消去または削除すると依頼が停止し、質問が閉じられ、待機も取り消され、古い会話の内容が消去したチャットに入ることはありません。"$json$::jsonb),
  ('de', 'whatsNew.item.clearStops.detail', $json$"Wurde ein Chat während seiner laufenden Anfrage geleert oder gelöscht, arbeitete der Agent unbemerkt weiter, und im geleerten Chat erschien seine Antwort allein, ohne die Anfrage. Eine offene Frage sperrte weiter das Nachrichtenfeld, und eine Anfrage, die auf das Nutzungslimit wartete, kam leer zurück. Jetzt stoppt Leeren oder Löschen die Anfrage, schließt die Frage und bricht das Warten ab, und nichts aus dem alten Gespräch erreicht den geleerten Chat."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.retryNote.title', $json$"\"Não funcionou\" vale só para o próprio pedido"$json$::jsonb),
  ('en', 'whatsNew.item.retryNote.title', $json$"\"It didn't work\" counts only for its own request"$json$::jsonb),
  ('es', 'whatsNew.item.retryNote.title', $json$"\"No funcionó\" vale solo para su propia solicitud"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.retryNote.title', $json$"“没成功”只对它自己的请求有效"$json$::jsonb),
  ('hi', 'whatsNew.item.retryNote.title', $json$"\"काम नहीं किया\" सिर्फ़ उसी अनुरोध पर लागू होता है"$json$::jsonb),
  ('ar', 'whatsNew.item.retryNote.title', $json$"«لم ينجح» يخص طلبه وحده"$json$::jsonb),
  ('fr', 'whatsNew.item.retryNote.title', $json$"« Ça n’a pas marché » ne vaut que pour sa propre demande"$json$::jsonb),
  ('ru', 'whatsNew.item.retryNote.title', $json$"«Не сработало» относится только к своему запросу"$json$::jsonb),
  ('ja', 'whatsNew.item.retryNote.title', $json$"「うまくいかなかった」はその依頼だけに適用されます"$json$::jsonb),
  ('de', 'whatsNew.item.retryNote.title', $json$"„Hat nicht funktioniert“ gilt nur für die eigene Anfrage"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.retryNote.detail', $json$"Quando a portaria barrava ou perguntava sobre uma mensagem como \"ainda dá erro\", o próximo pedido atendido depois dela — até de outro chat — chegava ao agente com o aviso de que a tentativa anterior tinha falhado. Agora o aviso vai só com o pedido que reclamou, ou com a confirmação dele."$json$::jsonb),
  ('en', 'whatsNew.item.retryNote.detail', $json$"When the gatehouse held or asked about a message like \"it still fails\", the next request served after it — even in another chat — reached the agent with the note that the previous attempt had failed. Now the note goes only with the request that complained, or with its confirmation."$json$::jsonb),
  ('es', 'whatsNew.item.retryNote.detail', $json$"Cuando la portería bloqueaba o preguntaba sobre un mensaje como \"sigue fallando\", la siguiente solicitud atendida después — incluso de otro chat — llegaba al agente con el aviso de que el intento anterior había fallado. Ahora el aviso va solo con la solicitud que se quejó, o con su confirmación."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.retryNote.detail', $json$"当门岗拦下或询问一条类似“还是出错”的消息时，之后处理的下一个请求（即使来自另一个聊天）会带着“上一次尝试失败了”的提示发送给代理。现在这条提示只随提出抱怨的请求或其确认一起发送。"$json$::jsonb),
  ('hi', 'whatsNew.item.retryNote.detail', $json$"जब गेट \"अब भी त्रुटि है\" जैसे संदेश को रोकता या उस पर सवाल पूछता था, तो उसके बाद संभाला गया अगला अनुरोध — किसी दूसरी चैट का भी — एजेंट तक इस सूचना के साथ पहुँचता था कि पिछली कोशिश विफल रही। अब यह सूचना सिर्फ़ शिकायत करने वाले अनुरोध या उसकी पुष्टि के साथ जाती है।"$json$::jsonb),
  ('ar', 'whatsNew.item.retryNote.detail', $json$"عندما كانت البوابة توقف رسالة مثل «ما زال يفشل» أو تسأل عنها، كان الطلب التالي الذي يُعالج بعدها — حتى من محادثة أخرى — يصل إلى الوكيل مع تنبيه بأن المحاولة السابقة فشلت. الآن يذهب التنبيه فقط مع الطلب الذي اشتكى، أو مع تأكيده."$json$::jsonb),
  ('fr', 'whatsNew.item.retryNote.detail', $json$"Quand la loge retenait ou interrogeait un message comme « ça échoue encore », la demande suivante traitée après lui — même d’un autre chat — arrivait à l’agent avec la note indiquant que la tentative précédente avait échoué. Désormais, la note n’accompagne que la demande qui s’est plainte, ou sa confirmation."$json$::jsonb),
  ('ru', 'whatsNew.item.retryNote.detail', $json$"Когда проходная задерживала сообщение вроде «всё ещё падает» или переспрашивала о нём, следующий обработанный после него запрос — даже из другого чата — доходил до агента с пометкой, что предыдущая попытка не удалась. Теперь пометка идёт только с запросом, который пожаловался, или с его подтверждением."$json$::jsonb),
  ('ja', 'whatsNew.item.retryNote.detail', $json$"「まだエラーになる」のようなメッセージをゲートが止めたり確認したりすると、その後に処理された次の依頼（別のチャットのものでも）に「前回の試行は失敗した」という注記が付いてエージェントに届いていました。今後、この注記は不満を伝えた依頼、またはその確認にだけ付きます。"$json$::jsonb),
  ('de', 'whatsNew.item.retryNote.detail', $json$"Wenn die Pforte eine Nachricht wie „schlägt immer noch fehl“ zurückhielt oder nachfragte, erreichte die danach bediente nächste Anfrage — sogar aus einem anderen Chat — den Agenten mit dem Hinweis, dass der vorige Versuch gescheitert sei. Jetzt geht der Hinweis nur mit der Anfrage, die sich beschwert hat, oder mit ihrer Bestätigung."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.nestedFolders.title', $json$"O chat geral da organização e os repositórios dela se revezam"$json$::jsonb),
  ('en', 'whatsNew.item.nestedFolders.title', $json$"An organization's general chat and its repositories take turns"$json$::jsonb),
  ('es', 'whatsNew.item.nestedFolders.title', $json$"El chat general de la organización y sus repositorios se turnan"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.nestedFolders.title', $json$"组织的通用聊天与其仓库轮流运行"$json$::jsonb),
  ('hi', 'whatsNew.item.nestedFolders.title', $json$"संगठन की सामान्य चैट और उसके रिपॉज़िटरी बारी-बारी चलते हैं"$json$::jsonb),
  ('ar', 'whatsNew.item.nestedFolders.title', $json$"المحادثة العامة للمؤسسة ومستودعاتها تتناوب"$json$::jsonb),
  ('fr', 'whatsNew.item.nestedFolders.title', $json$"Le chat général de l’organisation et ses dépôts se relaient"$json$::jsonb),
  ('ru', 'whatsNew.item.nestedFolders.title', $json$"Общий чат организации и её репозитории работают по очереди"$json$::jsonb),
  ('ja', 'whatsNew.item.nestedFolders.title', $json$"組織の総合チャットとそのリポジトリは順番に実行されます"$json$::jsonb),
  ('de', 'whatsNew.item.nestedFolders.title', $json$"Der allgemeine Chat einer Organisation und ihre Repositorys wechseln sich ab"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.nestedFolders.detail', $json$"Com mais de um pedido ao mesmo tempo no seu plano, um chat geral de uma organização (que trabalha na pasta dela) e o projeto de um dos repositórios dela (numa pasta dentro dela) podiam rodar juntos, com dois agentes escrevendo no mesmo repositório. Agora o projeto cuja pasta fica dentro da de outro espera por ele, como os pedidos de um mesmo projeto."$json$::jsonb),
  ('en', 'whatsNew.item.nestedFolders.detail', $json$"With more than one request at a time in your plan, a general chat of an organization (which works in the organization's folder) and a project of one of its repositories (in a folder inside it) could run together, with two agents writing to the same repository. Now a project whose folder is inside another's waits for it, like requests of the same project."$json$::jsonb),
  ('es', 'whatsNew.item.nestedFolders.detail', $json$"Con más de una solicitud a la vez en tu plan, un chat general de una organización (que trabaja en su carpeta) y el proyecto de uno de sus repositorios (en una carpeta dentro de ella) podían ejecutarse juntos, con dos agentes escribiendo en el mismo repositorio. Ahora el proyecto cuya carpeta está dentro de la de otro lo espera, como las solicitudes de un mismo proyecto."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.nestedFolders.detail', $json$"当你的套餐允许同时运行多个请求时，组织的通用聊天（在组织文件夹中工作）和其某个仓库的项目（在其中的子文件夹里）可能同时运行，导致两个代理写入同一个仓库。现在，文件夹位于另一个项目文件夹内的项目会等待它，就像同一项目的请求一样。"$json$::jsonb),
  ('hi', 'whatsNew.item.nestedFolders.detail', $json$"आपके प्लान में एक साथ एक से ज़्यादा अनुरोध की अनुमति होने पर, संगठन की सामान्य चैट (जो संगठन के फ़ोल्डर में काम करती है) और उसके किसी रिपॉज़िटरी का प्रोजेक्ट (उसके अंदर के फ़ोल्डर में) एक साथ चल सकते थे, यानी दो एजेंट एक ही रिपॉज़िटरी में लिखते थे। अब जिस प्रोजेक्ट का फ़ोल्डर दूसरे के फ़ोल्डर के अंदर है, वह उसका इंतज़ार करता है, जैसे एक ही प्रोजेक्ट के अनुरोध करते हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.nestedFolders.detail', $json$"عندما تسمح خطتك بأكثر من طلب في الوقت نفسه، كان يمكن أن تعمل المحادثة العامة لمؤسسة (التي تعمل في مجلد المؤسسة) ومشروع أحد مستودعاتها (في مجلد داخله) معًا، فيكتب وكيلان في المستودع نفسه. الآن ينتظر المشروع الذي يقع مجلده داخل مجلد مشروع آخر ذلك المشروع، كما تفعل طلبات المشروع الواحد."$json$::jsonb),
  ('fr', 'whatsNew.item.nestedFolders.detail', $json$"Avec plusieurs demandes simultanées dans votre forfait, un chat général d’une organisation (qui travaille dans son dossier) et le projet de l’un de ses dépôts (dans un dossier à l’intérieur) pouvaient s’exécuter ensemble, avec deux agents écrivant dans le même dépôt. Désormais, un projet dont le dossier est dans celui d’un autre l’attend, comme les demandes d’un même projet."$json$::jsonb),
  ('ru', 'whatsNew.item.nestedFolders.detail', $json$"Если ваш тариф разрешает несколько запросов одновременно, общий чат организации (работающий в её папке) и проект одного из её репозиториев (в папке внутри неё) могли выполняться вместе, и два агента писали в один репозиторий. Теперь проект, папка которого лежит внутри папки другого, ждёт его, как запросы одного проекта."$json$::jsonb),
  ('ja', 'whatsNew.item.nestedFolders.detail', $json$"プランで複数の依頼を同時に実行できる場合、組織の総合チャット（組織のフォルダーで作業）と、そのリポジトリのプロジェクト（その中のフォルダー）が同時に動き、2 つのエージェントが同じリポジトリに書き込むことがありました。今後は、フォルダーが別のプロジェクトのフォルダー内にあるプロジェクトは、同じプロジェクトの依頼と同様にそれを待ちます。"$json$::jsonb),
  ('de', 'whatsNew.item.nestedFolders.detail', $json$"Erlaubte Ihr Tarif mehrere Anfragen gleichzeitig, konnten ein allgemeiner Chat einer Organisation (der in ihrem Ordner arbeitet) und das Projekt eines ihrer Repositorys (in einem Ordner darin) zusammen laufen, mit zwei Agenten, die in dasselbe Repository schrieben. Jetzt wartet ein Projekt, dessen Ordner im Ordner eines anderen liegt, auf dieses, wie Anfragen desselben Projekts."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.stopUnstuck.title', $json$"O botão Parar não fica mais preso"$json$::jsonb),
  ('en', 'whatsNew.item.stopUnstuck.title', $json$"Stop no longer gets stuck"$json$::jsonb),
  ('es', 'whatsNew.item.stopUnstuck.title', $json$"El botón Detener ya no se queda atascado"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.stopUnstuck.title', $json$"“停止”按钮不再卡住"$json$::jsonb),
  ('hi', 'whatsNew.item.stopUnstuck.title', $json$"रोकें बटन अब अटकता नहीं"$json$::jsonb),
  ('ar', 'whatsNew.item.stopUnstuck.title', $json$"زر الإيقاف لم يعد يعلق"$json$::jsonb),
  ('fr', 'whatsNew.item.stopUnstuck.title', $json$"Le bouton Arrêter ne reste plus bloqué"$json$::jsonb),
  ('ru', 'whatsNew.item.stopUnstuck.title', $json$"Кнопка «Остановить» больше не залипает"$json$::jsonb),
  ('ja', 'whatsNew.item.stopUnstuck.title', $json$"停止ボタンが固まらなくなりました"$json$::jsonb),
  ('de', 'whatsNew.item.stopUnstuck.title', $json$"Die Schaltfläche Stoppen bleibt nicht mehr hängen"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.stopUnstuck.detail', $json$"Se o pedido para parar fosse recusado (uma sessão vencida, por exemplo), o botão Parar ficava desativado em \"Parando…\". Agora ele volta, e dá para tentar de novo."$json$::jsonb),
  ('en', 'whatsNew.item.stopUnstuck.detail', $json$"If stopping a request was refused (an expired session, for example), the Stop button stayed disabled as \"Stopping…\". Now it comes back so you can try again."$json$::jsonb),
  ('es', 'whatsNew.item.stopUnstuck.detail', $json$"Si se rechazaba detener una solicitud (una sesión vencida, por ejemplo), el botón Detener quedaba desactivado en \"Deteniendo…\". Ahora vuelve y puedes intentarlo de nuevo."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.stopUnstuck.detail', $json$"如果停止请求被拒绝（例如会话已过期），“停止”按钮会一直停留在“正在停止…”且无法点击。现在它会恢复，你可以再试一次。"$json$::jsonb),
  ('hi', 'whatsNew.item.stopUnstuck.detail', $json$"अगर अनुरोध रोकना अस्वीकार हो जाता (जैसे सत्र की अवधि खत्म होने पर), तो रोकें बटन \"रोका जा रहा है…\" पर निष्क्रिय रह जाता था। अब वह लौट आता है और आप फिर से कोशिश कर सकते हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.stopUnstuck.detail', $json$"إذا رُفض إيقاف الطلب (بسبب انتهاء الجلسة مثلًا)، كان زر الإيقاف يبقى معطلًا على «جارٍ الإيقاف…». الآن يعود فتستطيع المحاولة من جديد."$json$::jsonb),
  ('fr', 'whatsNew.item.stopUnstuck.detail', $json$"Si l’arrêt d’une demande était refusé (une session expirée, par exemple), le bouton Arrêter restait désactivé sur « Arrêt en cours… ». Désormais, il revient et vous pouvez réessayer."$json$::jsonb),
  ('ru', 'whatsNew.item.stopUnstuck.detail', $json$"Если остановка запроса отклонялась (например, из-за истёкшей сессии), кнопка «Остановить» оставалась неактивной в состоянии «Остановка…». Теперь она возвращается, и можно попробовать снова."$json$::jsonb),
  ('ja', 'whatsNew.item.stopUnstuck.detail', $json$"依頼の停止が拒否された場合（セッションの期限切れなど）、停止ボタンが「停止中…」のまま無効になっていました。今後はボタンが戻り、もう一度試せます。"$json$::jsonb),
  ('de', 'whatsNew.item.stopUnstuck.detail', $json$"Wurde das Stoppen einer Anfrage abgelehnt (etwa wegen einer abgelaufenen Sitzung), blieb die Schaltfläche Stoppen auf „Wird gestoppt…“ deaktiviert. Jetzt kehrt sie zurück, und Sie können es erneut versuchen."$json$::jsonb),
  ('pt-BR', 'docs.workModes.usage', $json$"Escolha o modo embaixo da caixa de mensagem, digite /plan, /build ou /auto no começo de uma mensagem, ou pressione Ctrl+. (⌘. no Mac). Quando um chat em Planejamento pede para implementar, o Jev o passa para Desenvolvimento. Em Desenvolvimento, o agente termina a resposta dizendo o que rodou, o que supõe e o que não verificou. Quando você dá uma permissão no chat (no seletor, em Executar ou em Sempre permitir), ela vale também no Auto: o pedido vai ao desenvolvimento, onde o agente pode usá-la. O Planejamento fixado continua só leitura. Recusar o plano ou pedir outro não o aprova, e o Jev só leva um plano ao Desenvolvimento sozinho enquanto nada mais foi enviado depois dele. O modo que você escolhe enquanto um pedido roda é mantido."$json$::jsonb),
  ('en', 'docs.workModes.usage', $json$"Pick the mode under the message box, type /plan, /build or /auto at the start of a message, or press Ctrl+. (⌘. on Mac). When a chat in Planning asks to implement, Jev switches it to Development. In Development the agent ends its answer with what it ran, what it assumes and what it did not verify. A permission you give in the chat (in the picker, Run or Always allow) also counts in Auto: the request goes to Development, where the agent can use it. A pinned Planning stays read-only. Refusing the plan or asking for another one does not approve it, and Jev only takes a plan to Development by itself while nothing else was sent after it. A mode you pick while a request runs is kept."$json$::jsonb),
  ('es', 'docs.workModes.usage', $json$"Elige el modo debajo del cuadro de mensaje, escribe /plan, /build o /auto al comienzo de un mensaje, o pulsa Ctrl+. (⌘. en Mac). Cuando un chat en Planificación pide implementar, Jev lo pasa a Desarrollo. En Desarrollo, el agente termina su respuesta diciendo qué ejecutó, qué supone y qué no verificó. Un permiso que das en el chat (en el selector, en Ejecutar o en Permitir siempre) también vale en Auto: la solicitud pasa a Desarrollo, donde el agente puede usarlo. Una Planificación fijada sigue siendo de solo lectura. Rechazar el plan o pedir otro no lo aprueba, y Jev solo lleva un plan a Desarrollo por su cuenta mientras no se haya enviado nada después. El modo que eliges mientras se ejecuta una solicitud se mantiene."$json$::jsonb),
  ('zh-CN', 'docs.workModes.usage', $json$"在消息框下方选择模式，在消息开头输入 /plan、/build 或 /auto，或按 Ctrl+.（Mac 上为 ⌘.）。当处于规划模式的聊天要求实现时，Jev 会把它切换到开发模式。在开发模式下，代理会在回答结尾说明它运行了什么、假设了什么、哪些没有验证。 你在聊天中给出的权限（在选择器中、点击“执行”或“始终允许”）在自动模式下同样有效：请求会进入开发模式，代理可以使用它。固定的规划模式仍然只读。拒绝计划或要求另做一个计划不会批准它；只有在计划之后没有再发送其他消息时，Jev 才会自行把计划带入开发模式。请求运行期间你选择的模式会被保留。"$json$::jsonb),
  ('hi', 'docs.workModes.usage', $json$"संदेश बॉक्स के नीचे मोड चुनें, संदेश की शुरुआत में /plan, /build या /auto टाइप करें, या Ctrl+. (Mac पर ⌘.) दबाएँ। जब योजना मोड वाली चैट लागू करने को कहती है, तो Jev उसे डेवलपमेंट में बदल देता है। डेवलपमेंट में एजेंट अपने जवाब के अंत में बताता है कि उसने क्या चलाया, क्या मान लिया और क्या सत्यापित नहीं किया। चैट में आपकी दी गई अनुमति (चयनकर्ता में, चलाएँ या हमेशा अनुमति दें से) ऑटो में भी मान्य होती है: अनुरोध विकास में जाता है, जहाँ एजेंट उसका उपयोग कर सकता है। पिन की गई योजना केवल-पठन ही रहती है। योजना को अस्वीकार करना या दूसरी योजना माँगना उसे स्वीकृत नहीं करता, और Jev किसी योजना को अपने-आप डेवलपमेंट में तभी ले जाता है जब उसके बाद कुछ और न भेजा गया हो। अनुरोध चलते समय आप जो मोड चुनते हैं, वही रहता है।"$json$::jsonb),
  ('ar', 'docs.workModes.usage', $json$"اختر الوضع أسفل مربع الرسالة، أو اكتب /plan أو /build أو /auto في بداية الرسالة، أو اضغط Ctrl+. (⌘. على Mac). عندما تطلب دردشة في وضع التخطيط التنفيذ، ينقلها Jev إلى التطوير. في التطوير يختم الوكيل إجابته بما شغّله وما يفترضه وما لم يتحقق منه. الإذن الذي تمنحه في المحادثة (من المحدّد أو «تنفيذ» أو «السماح دائمًا») يسري أيضًا في الوضع التلقائي: ينتقل الطلب إلى التطوير حيث يستطيع الوكيل استخدامه. ويبقى التخطيط المثبّت للقراءة فقط. رفض الخطة أو طلب خطة أخرى لا يوافق عليها، ولا ينقل Jev خطةً إلى التطوير من تلقاء نفسه إلا ما دام لم يُرسل شيء بعدها. والوضع الذي تختاره أثناء تنفيذ الطلب يبقى كما هو."$json$::jsonb),
  ('fr', 'docs.workModes.usage', $json$"Choisissez le mode sous la zone de message, tapez /plan, /build ou /auto au début d'un message, ou appuyez sur Ctrl+. (⌘. sur Mac). Quand un chat en Planification demande d'implémenter, Jev le passe en Développement. En Développement, l’agent termine sa réponse en disant ce qu’il a lancé, ce qu’il suppose et ce qu’il n’a pas vérifié. Une autorisation donnée dans le chat (dans le sélecteur, Exécuter ou Toujours autoriser) vaut aussi en Auto : la demande passe en Développement, où l’agent peut l’utiliser. Une Planification épinglée reste en lecture seule. Refuser le plan ou en demander un autre ne l’approuve pas, et Jev n’emmène un plan en Développement de lui-même que tant que rien d’autre n’a été envoyé après lui. Le mode que vous choisissez pendant qu’une demande s’exécute est conservé."$json$::jsonb),
  ('ru', 'docs.workModes.usage', $json$"Выберите режим под полем сообщения, введите /plan, /build или /auto в начале сообщения или нажмите Ctrl+. (⌘. на Mac). Когда в чате в режиме Планирования просят реализовать, Jev переключает его на Разработку. В режиме «Разработка» агент заканчивает ответ тем, что он запускал, что предполагает и что не проверил. Разрешение, которое вы даёте в чате (в переключателе, «Выполнить» или «Всегда разрешать»), действует и в режиме «Авто»: запрос уходит в разработку, где агент может им воспользоваться. Закреплённое планирование остаётся только для чтения. Отказ от плана или просьба о другом плане не одобряет его, а Jev сам переводит план в разработку, только пока после него ничего больше не отправлено. Режим, выбранный во время выполнения запроса, сохраняется."$json$::jsonb),
  ('ja', 'docs.workModes.usage', $json$"メッセージ欄の下でモードを選ぶか、メッセージの先頭に /plan、/build、/auto と入力するか、Ctrl+.（Mac では ⌘.）を押します。計画モードのチャットで実装を頼むと、Jev が開発モードに切り替えます。開発モードでは、エージェントは回答の最後に、実行したこと、前提としていること、検証していないことを述べます。 チャットで与えた許可（選択ツール、「実行」、「常に許可」）は自動モードでも有効です。リクエストは開発モードに進み、エージェントがその許可を使えます。固定した計画モードは読み取り専用のままです。計画を断る、または別の計画を求めても承認にはなりません。Jev が計画を自動で開発モードに進めるのは、その後に何も送られていないときだけです。依頼の実行中に選んだモードはそのまま保たれます。"$json$::jsonb),
  ('de', 'docs.workModes.usage', $json$"Wähle den Modus unter dem Nachrichtenfeld, tippe /plan, /build oder /auto am Anfang einer Nachricht oder drücke Strg+. (⌘. auf dem Mac). Wenn ein Chat in Planung um die Umsetzung bittet, wechselt Jev ihn in Entwicklung. In Entwicklung beendet der Agent seine Antwort mit dem, was er ausgeführt hat, was er annimmt und was er nicht geprüft hat. Eine Berechtigung, die Sie im Chat erteilen (in der Auswahl, mit Ausführen oder Immer erlauben), gilt auch im Automatikmodus: Die Anfrage geht in die Entwicklung, wo der Agent sie nutzen kann. Eine festgelegte Planung bleibt schreibgeschützt. Den Plan abzulehnen oder einen anderen zu verlangen genehmigt ihn nicht, und Jev bringt einen Plan nur von selbst in die Entwicklung, solange danach nichts anderes gesendet wurde. Ein Modus, den Sie wählen, während eine Anfrage läuft, bleibt erhalten."$json$::jsonb),
  ('pt-BR', 'docs.parallelRequests.usage', $json$"Não há nada para ligar: envie pedidos em chats de projetos diferentes e eles não esperam mais um pelo outro. Pedidos do mesmo projeto continuam um de cada vez, para dois agentes nunca escreverem na mesma pasta. O mesmo vale para um projeto cuja pasta fica dentro da de outro, como o chat geral de uma organização e os projetos dos repositórios dela."$json$::jsonb),
  ('en', 'docs.parallelRequests.usage', $json$"Nothing to turn on: send requests in chats of different projects and they no longer wait for each other. Requests in the same project still run one at a time, so two agents never write to the same folder. The same goes for a project whose folder is inside another one's, like an organization's general chat and the projects of its repositories."$json$::jsonb),
  ('es', 'docs.parallelRequests.usage', $json$"No hay nada que activar: envía solicitudes en chats de proyectos distintos y ya no se esperan entre sí. Las solicitudes del mismo proyecto siguen yendo de una en una, para que dos agentes nunca escriban en la misma carpeta. Lo mismo vale para un proyecto cuya carpeta está dentro de la de otro, como el chat general de una organización y los proyectos de sus repositorios."$json$::jsonb),
  ('zh-CN', 'docs.parallelRequests.usage', $json$"无需开启任何设置：在不同项目的聊天中发送请求，它们不再相互等待。同一项目的请求仍逐个进行，因此两个代理绝不会写入同一个文件夹。文件夹位于另一个项目文件夹之内的项目也是如此，例如组织的通用聊天与其各仓库的项目。"$json$::jsonb),
  ('hi', 'docs.parallelRequests.usage', $json$"कुछ चालू करने की ज़रूरत नहीं: अलग-अलग प्रोजेक्टों की चैट में अनुरोध भेजें, वे अब एक-दूसरे का इंतज़ार नहीं करते। एक ही प्रोजेक्ट के अनुरोध अब भी एक-एक करके चलते हैं, ताकि दो एजेंट कभी एक ही फ़ोल्डर में न लिखें। यही बात उस प्रोजेक्ट पर भी लागू होती है जिसका फ़ोल्डर किसी दूसरे प्रोजेक्ट के फ़ोल्डर के अंदर है, जैसे किसी संगठन की सामान्य चैट और उसके रिपॉज़िटरी के प्रोजेक्ट।"$json$::jsonb),
  ('ar', 'docs.parallelRequests.usage', $json$"لا شيء لتفعيله: أرسل طلبات في دردشات مشاريع مختلفة ولن ينتظر بعضها بعضًا. تبقى طلبات المشروع الواحد واحدًا تلو الآخر، كي لا يكتب وكيلان في المجلد نفسه أبدًا. وينطبق الأمر نفسه على مشروع يقع مجلده داخل مجلد مشروع آخر، مثل المحادثة العامة لمؤسسة ومشاريع مستودعاتها."$json$::jsonb),
  ('fr', 'docs.parallelRequests.usage', $json$"Rien à activer : envoyez des demandes dans des chats de projets différents et elles ne s'attendent plus. Les demandes d'un même projet passent toujours une par une, pour que deux agents n'écrivent jamais dans le même dossier. Il en va de même pour un projet dont le dossier est dans celui d’un autre, comme le chat général d’une organisation et les projets de ses dépôts."$json$::jsonb),
  ('ru', 'docs.parallelRequests.usage', $json$"Ничего включать не нужно: отправляйте запросы в чатах разных проектов, и они больше не ждут друг друга. Запросы одного проекта по-прежнему идут по одному, чтобы два агента никогда не писали в одну папку. То же касается проекта, папка которого лежит внутри папки другого, например общего чата организации и проектов её репозиториев."$json$::jsonb),
  ('ja', 'docs.parallelRequests.usage', $json$"設定は不要です。別々のプロジェクトのチャットで依頼を送れば、互いを待ちません。同じプロジェクトの依頼は引き続き 1 件ずつ処理され、2 つのエージェントが同じフォルダーに書き込むことはありません。フォルダーが別のプロジェクトのフォルダー内にあるプロジェクトも同様です（組織の総合チャットと、その各リポジトリのプロジェクトなど）。"$json$::jsonb),
  ('de', 'docs.parallelRequests.usage', $json$"Nichts einzuschalten: Sende Anfragen in Chats verschiedener Projekte, und sie warten nicht mehr aufeinander. Anfragen aus demselben Projekt laufen weiterhin nacheinander, damit nie zwei Agenten in denselben Ordner schreiben. Dasselbe gilt für ein Projekt, dessen Ordner in dem eines anderen liegt, etwa der allgemeine Chat einer Organisation und die Projekte ihrer Repositorys."$json$::jsonb),
  ('pt-BR', 'docs.stopRequest.usage', $json$"Enquanto um pedido roda, o botão Enviar vira Parar. Um pedido esperando na fila pode ser tirado dela. Todo pedido também para no tempo-limite definido em Configuração › Jev (30 minutos por padrão). Limpar ou excluir o chat também para o pedido dele que está rodando, e nada do que ele ainda devolveria entra no chat limpo."$json$::jsonb),
  ('en', 'docs.stopRequest.usage', $json$"While a request runs, the Send button turns into Stop. A request waiting in the queue can be removed from it. Every request also stops at the time limit set in Settings › Jev (30 minutes by default). Clearing or deleting the chat also stops its running request, and nothing it still returns reaches the cleared chat."$json$::jsonb),
  ('es', 'docs.stopRequest.usage', $json$"Mientras se ejecuta una solicitud, el botón Enviar se convierte en Detener. Una solicitud que espera en la cola se puede quitar de ella. Toda solicitud también se detiene al llegar al límite de tiempo definido en Configuración › Jev (30 minutos de forma predeterminada). Vaciar o eliminar el chat también detiene su solicitud en curso, y nada de lo que aún devolvería entra en el chat vaciado."$json$::jsonb),
  ('zh-CN', 'docs.stopRequest.usage', $json$"请求运行时，“发送”按钮会变成“停止”。在队列中等待的请求可以从队列中移除。每个请求也会在设置 › Jev 中设定的时间上限（默认 30 分钟）时停止。清空或删除聊天也会停止其正在运行的请求，它之后返回的内容不会进入已清空的聊天。"$json$::jsonb),
  ('hi', 'docs.stopRequest.usage', $json$"अनुरोध चलते समय भेजें बटन रोकें बन जाता है। कतार में इंतज़ार कर रहे अनुरोध को उससे हटाया जा सकता है। हर अनुरोध सेटिंग्स › Jev में तय समय-सीमा (डिफ़ॉल्ट 30 मिनट) पर भी रुक जाता है। चैट साफ़ करने या हटाने पर उसका चल रहा अनुरोध भी रुक जाता है, और वह जो कुछ अभी लौटाता, वह साफ़ की गई चैट में नहीं आता।"$json$::jsonb),
  ('ar', 'docs.stopRequest.usage', $json$"أثناء تشغيل الطلب، يتحول زر إرسال إلى إيقاف. ويمكن إزالة الطلب المنتظر في الطابور منه. ويتوقف كل طلب أيضًا عند الحد الزمني المضبوط في الإعدادات › Jev (30 دقيقة افتراضيًا). ويؤدي مسح المحادثة أو حذفها أيضًا إلى إيقاف طلبها الجاري، ولا يدخل المحادثة الممسوحة شيءٌ مما كان سيعيده."$json$::jsonb),
  ('fr', 'docs.stopRequest.usage', $json$"Pendant qu'une demande s'exécute, le bouton Envoyer devient Arrêter. Une demande en attente dans la file peut en être retirée. Toute demande s'arrête aussi à la limite de temps définie dans Configuration › Jev (30 minutes par défaut). Vider ou supprimer le chat arrête aussi sa demande en cours, et rien de ce qu’elle renverrait encore n’arrive dans le chat vidé."$json$::jsonb),
  ('ru', 'docs.stopRequest.usage', $json$"Пока запрос выполняется, кнопка «Отправить» превращается в «Остановить». Запрос, ожидающий в очереди, можно из неё убрать. Каждый запрос также останавливается по лимиту времени из раздела Настройки › Jev (по умолчанию 30 минут). Очистка или удаление чата тоже останавливает его выполняющийся запрос, и ничего из того, что он ещё вернул бы, не попадает в очищенный чат."$json$::jsonb),
  ('ja', 'docs.stopRequest.usage', $json$"依頼の実行中は送信ボタンが停止ボタンに変わります。キューで待っている依頼はキューから外せます。すべての依頼は設定 › Jev で決めた制限時間（既定は 30 分）でも停止します。チャットを消去または削除すると、実行中の依頼も停止し、その後に返ってくる内容が消去したチャットに入ることはありません。"$json$::jsonb),
  ('de', 'docs.stopRequest.usage', $json$"Während eine Anfrage läuft, wird aus dem Button Senden ein Stoppen. Eine Anfrage, die in der Warteschlange wartet, lässt sich daraus entfernen. Jede Anfrage stoppt außerdem am Zeitlimit aus Einstellungen › Jev (standardmäßig 30 Minuten). Das Leeren oder Löschen des Chats stoppt auch seine laufende Anfrage, und nichts, was sie noch zurückgeben würde, landet im geleerten Chat."$json$::jsonb)
